        class TestForm(forms.ModelForm):
            class Meta:
                model = Category
                fields = ['name', 'slug', 'url']
        form = TestForm()
        self.assertTrue(form.instance._state.adding)
        self.assertEqual(form.initial, {})

    def test_initializes_with_existing_instance(self):
        category = Category.objects.create(name='Test', slug='test', url='test')
        class TestForm(forms.ModelForm):
            class Meta:
                model = Category
                fields = ['name', 'slug', 'url']
        form = TestForm(instance=category)
        self.assertEqual(form.instance, category)
        self.assertEqual(form.initial['name'], 'Test')
        self.assertEqual(form.initial['slug'], 'test')
        self.assertEqual(form.initial['url'], 'test')

    def test_initial_data_overrides_instance(self):
        category = Category.objects.create(name='Original', slug='original', url='original')
        class TestForm(forms.ModelForm):
            class Meta:
                model = Category
                fields = ['name', 'slug', 'url']
        form = TestForm(instance=category, initial={'name': 'New'})
        self.assertEqual(form.initial['name'], 'New')
        self.assertEqual(form.initial['slug'], 'original')
        self.assertEqual(form.initial['url'], 'original')

    def test_raises_value_error_when_model_not_set(self):
