            class Meta:
                fields = ['name']
        with self.assertRaises(ValueError) as cm:
            NoModelForm()
        self.assertEqual(
            str(cm.exception),
            "ModelForm has no model class specified."
        )

    def test_applies_limit_choices_to_to_formfields(self):
