class BaseModelFormValidateUniqueTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        # Create a category with a unique slug
        cls.category1 = Category.objects.create(name='Test1', slug='unique', url='url1')
        cls.category2 = Category.objects.create(name='Test2', slug='another', url='url2')

    def test_validate_unique_excludes_meta_excluded_fields(self):
        class SlugExcludingCategoryForm(forms.ModelForm):
            class Meta:
                model = Category
                exclude = ['slug']

        # Form data for a new category with same slug as category1 (but slug is excluded)
        data = {'name': 'Test3', 'url': 'url3'}
        form = SlugExcludingCategoryForm(data)
        # Set instance's slug to duplicate
        form.instance = Category(slug='unique')

        try:
            form.validate_unique()
        except ValidationError:
            self.fail("Fields excluded via Meta.exclude should not be validated for uniqueness.")

    def test_validate_unique_includes_fields_when_not_excluded(self):
        class FullCategoryForm(forms.ModelForm):
            class Meta:
                model = Category
                fields = '__all__'

        # Form data with duplicate slug
        data = {'name': 'Test3', 'slug': 'unique', 'url': 'url3'}
        form = FullCategoryForm(data)
        form.is_valid()  # Ensure cleaned_data is populated

        with self.assertRaises(ValidationError):
            form.validate_unique()

    def test_validate_unique_excludes_fields_with_form_errors(self):
        class CategoryForm(forms.ModelForm):
            class Meta:
                model = Category
                fields = '__all__'

        # Form data with invalid slug (duplicate) and another field error
        data = {'name': '', 'slug': 'unique', 'url': 'url3'}
        form = CategoryForm(data)
        form.is_valid()  # Triggers validation, name field error added

        with self.assertRaises(ValidationError) as cm:
            form.validate_unique()
        # The unique error should still be raised since 'slug' is not excluded
        self.assertIn('slug', str(cm.exception))

    def test_validate_unique_excludes_blank_non_required_fields(self):
        # Modify category model's 'url' field to be blankable for test
        from django.db.models import CharField
        orig_url_field = Category._meta.get_field('url')
        orig_url_field.blank = True
        try:
            class CategoryForm(forms.ModelForm):
                class Meta:
                    model = Category
                    fields = '__all__'

            # Create instance with duplicate slug and blank url
            data = {'name': 'TestBlank', 'slug': 'unique', 'url': ''}
            form = CategoryForm(data)
            form.is_valid()  # Ensure cleaned_data is populated

            # Mock url field to be non-required and blank
            form.fields['url'].required = False
            form.cleaned_data['url'] = ''

            with self.assertRaises(ValidationError) as cm:
                form.validate_unique()
            # The unique error on slug should still be raised
            self.assertIn('slug', str(cm.exception))
        finally:
            # Restore original field settings
            orig_url_field.blank = False
